import { TinyColor } from "@ctrl/tinycolor"
import { RgbaColorPicker, type RgbaColor } from "react-colorful"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

type ColorInputProps = {
  id: string
  label: string
  value: string
  disabled?: boolean
  compact?: boolean
  placeholder?: string
  onChange: (value: string) => void
}

/** Manual CSS text is preserved; only a visual edit serializes a new CSS color. */
export function ColorInput({ id, label, value, disabled, compact = false, placeholder, onChange }: ColorInputProps) {
  const parsed = new TinyColor(value)
  const color = parsed.isValid ? parsed.toRgb() : { r: 0, g: 0, b: 0, a: 1 }
  const changeColor = (next: RgbaColor) => {
    const css = new TinyColor(next)
    onChange(next.a === 1 ? css.toHexString() : css.toRgbString())
  }
  const textInput = <Input id={id} value={value} disabled={disabled} placeholder={placeholder}
    aria-label={compact ? `${label} color value` : undefined}
    className="min-w-0 flex-1" onChange={(event) => onChange(event.target.value)} />
  return (
    <div className="flex w-full min-w-0 items-center gap-2" data-slot="color-input">
      <Popover>
        <PopoverTrigger asChild>
          <Button type="button" variant="outline" size={compact ? "icon-xs" : "icon"} disabled={disabled}
            aria-label={`Choose ${label} color`} className="shrink-0 p-1">
            <span className="relative size-full overflow-hidden rounded-sm border border-border"
              style={{ backgroundColor: "#fff", backgroundImage: "conic-gradient(#ddd 25%, #fff 0 50%, #ddd 0 75%, #fff 0)", backgroundSize: "8px 8px" }}>
              <span className="absolute inset-0" style={{ backgroundColor: parsed.isValid ? parsed.toRgbString() : "transparent" }} />
            </span>
          </Button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-64 space-y-3" aria-label={`${label} color picker`}>
          <div className="text-sm font-medium">{label}</div>
          <RgbaColorPicker color={color} onChange={changeColor} style={{ width: "100%" }} />
          {compact ? textInput : null}
          <div className="flex items-center justify-between gap-3">
            <Label htmlFor={`${id}-opacity`}>Opacity</Label>
            <div className="flex items-center gap-1">
              <Input id={`${id}-opacity`} type="number" min={0} max={100} step={1}
                className="w-20" value={Math.round(color.a * 100)}
                onChange={(event) => {
                  if (event.target.value === "") return
                  const opacity = Number(event.target.value)
                  if (Number.isFinite(opacity)) changeColor({ ...color, a: Math.max(0, Math.min(100, opacity)) / 100 })
                }} />
              <span className="text-sm text-muted-foreground">%</span>
            </div>
          </div>
        </PopoverContent>
      </Popover>
      {compact ? null : textInput}
    </div>
  )
}
